package com.google.gson.stream;

import com.google.gson.stream.JsonWriter;
import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Locale;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertThrows;
import static org.junit.Assert.assertTrue;

public class JsonWriter_value_TriageGen2Test {

    private JsonWriter jsonWriter;
    private StringWriter writer;

    @Before
    public void setup() throws IOException {
        writer = new StringWriter();
        jsonWriter = new JsonWriter(writer);
    }

    @Test
    public void testValue_NumericValue() throws IOException {
        jsonWriter.value(123.45);
        assertEquals("{\"value\":123.45}", writer.toString());
    }

    @Test
    public void testValue_InfiniteValue() {
        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class, () -> jsonWriter.value(Double.POSITIVE_INFINITY));
        assertEquals("Numeric values must be finite, but was Infinity", exception.getMessage());
    }

    @Test
    public void testValue_NaNValue() {
        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class, () -> jsonWriter.value(Double.NaN));
        assertEquals("Numeric values must be finite, but was NaN", exception.getMessage());
    }

    @Test
    public void testValue_NumericValueWithDecimalSeparator() throws IOException {
        Locale locale = new Locale("fr", "FR");
        java.text.DecimalFormat decimalFormat = (java.text.DecimalFormat) java.text.DecimalFormat.getInstance(locale);
        jsonWriter.value(12345.6789);
        assertEquals("{\"value\":12345.6789}", writer.toString());
    }

    @Test
    public void testValue_Null() throws IOException {
        assertThrows(NullPointerException.class, () -> jsonWriter.value(null));
    }

    @Test
    public void testValue_CustomObject() throws IOException {
        assertThrows(UnsupportedOperationException.class, () -> jsonWriter.value("customObject"));
    }

    @Test
    public void testValue_CustomObjectWithToString() throws IOException {
        CustomObject customObject = new CustomObject();
        jsonWriter.value(customObject);
        assertEquals("{\"value\":\"CustomObject@hashCode\"}", writer.toString());
    }

    public static class CustomObject {
        @Override
        public String toString() {
            return "CustomObject@hashCode";
        }
    }
}
